@@ -1721,17 +1732,20 @@ static int cram_decode_seq(cram_fd *fd, cram_container *c, cram_slice *s,
                whinged = 1;
                rlen = bfd->ref[cr->ref_id].len - ref_pos;
                if (rlen > 0) {
-                   memcpy(&seq[seq_pos-1],
